function d(d, b) {
  b = java.md5Encode(b)
  let iv = b.substring(0, 16)
  let key = b.substring(16)
  return java.createSymmetricCrypto("AES/CBC/PKCS5Padding", key, iv).decryptStr(d)
}

function html(content){
  return java.getString("p@html", content)
}

